class EPGManager:
    def __init__(self, data: dict):
        self._programmes = data


    def has_data(self) -> bool:
        return bool(self._programmes)

    def get_channel_name(self, tvg_id: str) -> str:
        return str(tvg_id)

    @staticmethod
    def _entry_to_programme(e: dict) -> Programme:
        return Programme(
            channel  = e.get('channel', ''),
            start    = e.get('start_timestamp', 0),
            stop     = e.get('stop_timestamp',  0),
            title    = e.get('name',            ''),
            desc     = e.get('descr',           ''),
            category = e.get('category',        ''),
            episode  = e.get('episode',         ''),
            icon     = e.get('screenshot_uri',  ''),
            rating   = e.get('rating',          ''),
        )

    def get_current(self, tvg_id: str, now: float = None) -> Programme:
        if now is None:
            now = time.time()
        for e in self._programmes.get(str(tvg_id), []):
            s = e.get('start_timestamp', 0)
            t = e.get('stop_timestamp',  0)
            if s <= now < t:
                return self._entry_to_programme(e)
        return None

    def get_range(self, tvg_id: str, from_ts: float, to_ts: float):
        result = []
        for e in self._programmes.get(str(tvg_id), []):
            s = e.get('start_timestamp', 0)
            t = e.get('stop_timestamp',  0)
            if t > from_ts and s < to_ts:
                result.append(self._entry_to_programme(e))
        return result

"""One private resumable wizard intent, never a production portal or password.

Small state checkpoints retain selections separately from the source catalogue.
No xc_pass, raw provider response, GUI property or exception string is persisted.
The existing worker lease must outlive the last checkpoint and staging cleanup.
"""
import contextlib,hashlib,json,os,shutil,sqlite3,stat,tempfile,threading,time,uuid
from urllib.parse import urlsplit,urlunsplit,parse_qsl,urlencode
_local=threading.local()
KINDS=('live','vod','series');MAX_BYTES=2*1024*1024
NONSECRET=('type','name','xc_host','xc_user','stb_url','stb_mac','stb_serial','stb_device_id','epg_show','enabled','start_group_id','start_stream_id')


def current():return getattr(_local,'session',None)


@contextlib.contextmanager
def using(session):
    before=current();_local.session=session
    try:yield session
    finally:_local.session=before


def root():
    from utils import addon_data_dir
    return os.path.join(addon_data_dir(),'wizard_resume53')


def private_folder(path):
    if os.path.islink(path):raise OSError('DRAFT_STORAGE_UNSAFE')
    os.makedirs(path,mode=0o700,exist_ok=True)
    from wizard_storage71 import protect
    protect(path,directory=True)


def write_file(path,value):
    private_folder(os.path.dirname(path))
    if os.path.islink(path):raise OSError('DRAFT_STORAGE_UNSAFE')
    raw=json.dumps(value,ensure_ascii=False,separators=(',',':')).encode()
    if len(raw)>MAX_BYTES:raise ValueError('DRAFT_BUDGET')
    fd,temp=tempfile.mkstemp(prefix='.wizard53-',dir=os.path.dirname(path))
    try:
        from wizard_storage71 import protect
        protect(temp,fd=fd)
        with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
        fd=None;os.replace(temp,path);temp=None
    finally:
        if fd is not None:
            try:os.close(fd)
            except OSError:pass
        if temp:
            try:os.unlink(temp)
            except OSError:pass


def read_file(path):
    if os.path.islink(path) or not os.path.isfile(path):return None
    from wizard_storage71 import readable
    if not readable(path):return None
    with open(path,encoding='utf-8') as f:raw=f.read(MAX_BYTES+1)
    if len(raw)>MAX_BYTES:raise ValueError('DRAFT_BUDGET')
    return json.loads(raw)


def safe_data(data):
    value={key:data[key] for key in NONSECRET if isinstance(data.get(key),(str,bool))}
    # Token-bearing playlist/custom URLs are not password-free restart data.
    # The source is re-entered; an ordinary origin/path without credentials or
    # query can be retained. No secret hash is kept as a substitute password.
    for key in ('m3u_url','epg_url'):
        uri=str(data.get(key) or '')
        parsed=urlsplit(uri)
        sensitive={'password','pass','token','auth','api_key','apikey','access_token'}
        query=parse_qsl(parsed.query,keep_blank_values=True)
        private=bool(parsed.username or parsed.password or any(k.casefold() in sensitive for k,v in query))
        if uri and not private:value[key]=uri
        elif uri:
            host=parsed.hostname or ''
            if parsed.port:host+=':'+str(parsed.port)
            clean=urlunsplit((parsed.scheme,host,parsed.path,urlencode([(k,v) for k,v in query if k.casefold() not in sensitive]),''))
            value[key+'_public53']=clean;value[key+'_needs_input53']=True
    return value


class Session:
    def __init__(self,state=None):
        self.state=state or dict(version=1,token=uuid.uuid4().hex,created=time.time(),status='ACTIVE',stage='input',selected={k:[] for k in KINDS})
        self.data=dict(self.state.get('data',{}));self.live=None;self.error='';self.action='';self._lock=threading.RLock()
    @classmethod
    def load(cls):
        try:
            if os.path.islink(root()) or not os.path.isdir(root()):return None
            from wizard_storage71 import readable
            if not readable(root()):return None
            value=read_file(os.path.join(root(),'current.json'))
            if not isinstance(value,dict) or value.get('version')!=1 or value.get('status')!='ACTIVE':return None
            if not isinstance(value.get('token'),str) or len(value['token'])!=32:return None
            session=cls(value)
            session.state['revalidate53']=time.time()-float(value.get('updated',0))>86400
            return session
        except (OSError,ValueError,TypeError):return None
    def persist(self):
        try:
            self.state['data']=safe_data(self.data);self.state['updated']=time.time()
            write_file(os.path.join(root(),'current.json'),self.state);self.error='';return True
        except (OSError,ValueError,TypeError) as exc:
            self.error='DRAFT_STORAGE_UNAVAILABLE';self.errno71=getattr(exc,'errno',None)
            from setup_diagnostics71 import emit
            emit('CHECKPOINT_FAILED',self.state.get('pid',self.state['token']),error=exc,path='ADDON_DATA')
            return False
    def input(self,data,key=None):
        with self._lock:
            self.data=dict(data);self.state['stage']='input';self.state['input_key']=key or ''
            if key=='name':self.state['name_confirmed']=True
            return self.persist()
    def checkpoint(self,draft,stage=None,categories=False):
        with self._lock:
            # A delayed worker cannot resurrect an explicitly discarded or
            # completed intent after its GUI has closed.
            if self.state.get('status')!='ACTIVE':return False
            self.data={k:v for k,v in draft.data.items() if k!='id'}
            self.state['name_confirmed']=True
            self.state.update(pid=draft.pid,folder=os.path.basename(draft.folder),stage=stage or self.state.get('stage','groups'),
                selected={k:sorted(draft.selected[k]) for k in KINDS},provider_epg=bool(draft.provider_epg),
                epg_sources=[dict(s) for s in draft.epg_sources],scanned=bool(draft.scanned),signature=draft._scan_signature,
                report={k:draft.report.get(k,0) for k in ('groups','live','vod','series','epg')})
            if getattr(draft,'phased54',False):self.state.update(phased54=True,published54=bool(draft.saved))
            try:
                private_folder(draft.folder)
                stages=list(self.state.get('staging53',[]));record=dict(folder=os.path.basename(draft.folder),pid=draft.pid)
                if record not in stages:
                    if len(stages)>=4:raise ValueError('DRAFT_STAGE_BUDGET')
                    stages.append(record)
                write_file(os.path.join(draft.folder,'owner53.json'),dict(token=self.state['token'],pid=draft.pid))
                self.state['staging53']=stages
                # Existing staging can contain private stream/artwork URLs.
                # Enforce real file modes before allowing restart reuse.
                for filename in os.scandir(draft.folder):
                    if filename.is_symlink():raise OSError('DRAFT_STORAGE_UNSAFE')
                    if filename.is_file():
                        from wizard_storage71 import protect
                        protect(filename.path)
                if categories:
                    clean={kind:[dict(category_id=str(g['category_id'])[:512],category_name=str(g['category_name'])[:512]) for g in draft.categories[kind]][:20000] for kind in KINDS}
                    if any(len(draft.categories[k])>20000 for k in KINDS):raise ValueError('DRAFT_BUDGET')
                    write_file(os.path.join(draft.folder,'categories53.json'),clean)
                ok=self.persist()
                if ok:
                    from setup_diagnostics71 import emit
                    emit('CHECKPOINT_DONE',draft.pid)
                return ok
            except (OSError,ValueError,TypeError) as exc:
                self.error='DRAFT_STORAGE_UNAVAILABLE';self.errno71=getattr(exc,'errno',None)
                from setup_diagnostics71 import emit
                emit('CHECKPOINT_FAILED',draft.pid,error=exc,path='ADDON_DATA')
                return False
    def folder(self):
        from utils import addon_data_dir
        name=self.state.get('folder','')
        if not isinstance(name,str) or not name.startswith('xcmate-setup-') or os.path.basename(name)!=name:return None
        path=os.path.join(addon_data_dir(),name)
        from wizard_storage71 import readable
        if os.path.islink(path) or not os.path.isdir(path) or not readable(path):return None
        try:owner=read_file(os.path.join(path,'owner53.json'))
        except (OSError,ValueError):return None
        if owner!=dict(token=self.state['token'],pid=self.state.get('pid')):return None
        return path
    def restore(self,data):
        from setup_draft import Draft
        from source_adapters import for_portal
        # Reuse RAM state, but re-authenticate if the user edited credentials.
        prior=self.live
        if prior is not None and not prior.saved:
            changed=any(prior.data.get(k)!=data.get(k) for k in ('type','xc_host','xc_user','m3u_url','stb_url','stb_mac'))
            if not changed:
                if prior.data.get('xc_pass')!=data.get('xc_pass'):self.authenticated53=False
                prior.data.update(data);prior.adapter=for_portal(prior.data,filename=prior.index,playlist=prior.playlist);return prior
        if len(self.state.get('staging53',[]))>=4 and prior is not None:raise ValueError('DRAFT_STAGE_BUDGET')
        draft=Draft(data);draft.phased54=bool(self.state.get('phased54'));folder=self.folder()
        if prior is not None:
            draft.selected={k:set(prior.selected[k]) for k in KINDS}
            draft.epg_sources=list(prior.epg_sources);draft.provider_epg=prior.provider_epg
        if any(self.state.get('data',{}).get(k)!=data.get(k) for k in ('type','xc_host','xc_user','stb_url','stb_mac')):folder=None
        self.live=draft
        if folder is None:return draft
        pid=str(self.state.get('pid',''))
        try:uuid.UUID(pid)
        except (ValueError,AttributeError):return draft
        from portals import get_by_id
        if get_by_id(pid) is not None:return draft
        try:
            categories=read_file(os.path.join(folder,'categories53.json'))
            if not isinstance(categories,dict):return draft
            # Drop only the unused, just-created empty private folder.
            os.rmdir(draft.folder);draft.folder=folder;draft.pid=pid;draft.data['id']=pid
            draft.index=os.path.join(folder,'library.sqlite');draft.guide=os.path.join(folder,'guide.sqlite');draft.playlist=os.path.join(folder,'playlist.sqlite')
            draft.categories={k:list(categories.get(k,[])) for k in KINDS}
            draft.selected={k:set(map(str,self.state.get('selected',{}).get(k,[]))) for k in KINDS}
            draft.provider_epg=bool(self.state.get('provider_epg'));draft.epg_sources=list(self.state.get('epg_sources',[]))
            draft.report.update(self.state.get('report',{}));draft._scan_signature=self.state.get('signature')
            draft.adapter=for_portal(draft.data,filename=draft.index,playlist=draft.playlist)
            # Only a validated owned .53 folder for the same Xtream account
            # may bootstrap old atomic group heads into .54 receipts.
            draft._trusted_legacy54=bool(draft.data.get('type')=='xtream' and not self.state.get('revalidate53'))
            draft._legacy_selected54={k:set(draft.selected[k]) for k in KINDS}
            if self.state.get('scanned') and not self.state.get('revalidate53') and os.path.isfile(draft.index):
                db=sqlite3.connect('file:'+__import__('urllib.parse',fromlist=['quote']).quote(draft.index,safe='/')+'?mode=ro',uri=True,timeout=.05)
                try:draft.scanned=db.execute('PRAGMA quick_check').fetchone()[0]=='ok' and draft._scan_signature==draft._signature()
                finally:db.close()
        except (OSError,sqlite3.Error,ValueError,TypeError):draft.scanned=False
        return draft
    def _cleanup_stages(self):
        from utils import addon_data_dir
        for row in self.state.get('staging53',[])[:4]:
            name=row.get('folder','')
            if not name.startswith('xcmate-setup-') or os.path.basename(name)!=name:continue
            folder=os.path.join(addon_data_dir(),name)
            if os.path.islink(folder) or not os.path.isdir(folder):continue
            try:owner=read_file(os.path.join(folder,'owner53.json'))
            except (OSError,ValueError):continue
            if owner==dict(token=self.state['token'],pid=row.get('pid')):
                # .53 source archives have no .54 source/configuration receipt.
                # Preserve that older unpublished EPG instead of discarding it
                # when the newly separated catalogue setup completes.
                if self.state.get('phased54') and os.path.isfile(os.path.join(folder,'guide.sqlite')):continue
                shutil.rmtree(folder,ignore_errors=True)
    def completed(self):
        with self._lock:
            self.state['status']='COMPLETE';ok=self.persist()
            if self.live is None:self._cleanup_stages()
            return ok
    def discard(self,confirmed=False):
        if not confirmed:return False
        with self._lock:
            self.state['status']='DISCARDED';ok=self.persist()
            if self.live is None:self._cleanup_stages()
            return ok
    def detached(self,draft):
        if draft.saved and getattr(draft,'phased54',False):
            from wizard_epg54 import pending
            if pending(draft.data):
                self.checkpoint(draft,'epg_pending');self.live=None;return
            self.completed();self._cleanup_stages();self.live=None
        elif draft.saved:self.completed();self._cleanup_stages();self.live=None
        elif self.state.get('status')=='DISCARDED':self._cleanup_stages();self.live=None
        else:self.checkpoint(draft)


def unreadable_intent():
    """Do not silently overwrite an existing corrupt/unsafe ACTIVE intent."""
    filename=os.path.join(root(),'current.json')
    if not os.path.lexists(filename):return False
    try:
        from wizard_storage71 import readable
        if os.path.islink(root()) or not readable(root()):return True
        value=read_file(filename)
        if isinstance(value,dict) and value.get('version')==1 and value.get('status') in ('COMPLETE','DISCARDED'):return False
        return Session.load() is None
    except (OSError,ValueError,TypeError):return True

"""Post-publication, independently resumable EPG sources on the existing guide.

Same cross-interpreter portal lease, import budget, backup gate and source
publisher as regular refresh. No fixed job duration. Receipts contain no URLs
or secrets; only completely validated and re-read sources can be skipped.
"""
import hashlib,json,os,sqlite3,time,uuid
from urllib.parse import quote


def path(portal):
    from utils import addon_data_dir
    return os.path.join(addon_data_dir(),'epg_setup54_'+hashlib.sha256(str(portal['id']).encode()).hexdigest()[:24]+'.json')


def read(portal):
    from wizard_resume53 import read_file
    try:
        value=read_file(path(portal))
        return value if isinstance(value,dict) and value.get('version')==1 and value.get('pid')==str(portal['id']) else None
    except (OSError,ValueError,TypeError):return None


def write(portal,state):
    # Existing profile permissions are not changed by the private-file writer.
    import tempfile,stat
    filename=path(portal);temp=None;raw=json.dumps(state,separators=(',',':')).encode()
    if len(raw)>1024*1024 or os.path.islink(filename):raise OSError('EPG_CHECKPOINT_UNSAFE')
    fd,temp=tempfile.mkstemp(prefix='.epg-setup54-',dir=os.path.dirname(filename))
    try:
        from wizard_storage71 import protect
        protect(temp,fd=fd)
        with os.fdopen(fd,'wb') as f:
            fd=None;f.write(raw);f.flush();os.fsync(f.fileno())
        os.replace(temp,filename);temp=None
    finally:
        if fd is not None:os.close(fd)
        if temp:
            try:os.unlink(temp)
            except OSError:pass


def prepare(portal):
    state=read(portal)
    if state is None:
        from epg_sources import configuration
        enabled=portal.get('provider_epg_enabled',True) or any(s.get('enabled',True) for s in configuration(portal['id'])['sources'])
        state=dict(version=1,pid=str(portal['id']),phase='PENDING' if enabled else 'NONE',sources={},updated=time.time())
        write(portal,state)
    return state


def pending(portal):
    state=read(portal)
    return bool(state and state.get('phase') not in ('READY','NONE'))


def signature(portal,source,rank):
    from epg_sources import configuration
    from library_index import connect
    db=connect();heads=[]
    try:
        if db is not None:heads=[tuple(r) for r in db.execute("SELECT cid,generation FROM heads WHERE pid=? AND kind='live' ORDER BY cid",(str(portal['id']),))]
    finally:
        if db is not None:db.close()
    conf=configuration(portal['id'])
    # Only a one-way configuration identity is persisted, never the URI.
    return hashlib.sha256(json.dumps([54,source,rank,heads,conf['mappings'],getattr(conf['mappings'],'sources48',{})],sort_keys=True).encode()).hexdigest()


def stored(portal,identity,cancel=lambda:False,status=lambda *a:None):
    from guide_store import path as guide_path
    if not os.path.isfile(guide_path()):return None
    db=sqlite3.connect('file:'+quote(guide_path(),safe='/')+'?mode=ro',uri=True,timeout=.1)
    try:
        db.execute('PRAGMA query_only=ON');db.execute('BEGIN')
        # Cancels cooperatively even inside quick_check / large SQL sorting.
        db.set_progress_handler(lambda:int(cancel()),1000)
        if db.execute('PRAGMA quick_check').fetchone()[0]!='ok':return None
        h=hashlib.sha256();count=0;first=None;last=None
        for row in db.execute('SELECT cid,start,stop,title,description,rank FROM guide44_inputs WHERE pid=? AND source_id=? ORDER BY cid,start,stop',(str(portal['id']),identity)):
            if cancel():raise InterruptedError('EPG_CANCELLED')
            h.update(json.dumps(row,ensure_ascii=False,separators=(',',':')).encode());h.update(b'\n');count+=1
            first=row[1] if first is None else min(first,row[1]);last=row[2] if last is None else max(last,row[2])
            if count%1024==0:status(None,'Gespeicherte EPG-Daten werden geprüft · '+str(count)+' Sendungen')
        return dict(rows=count,digest=h.hexdigest(),first=first,last=last)
    except sqlite3.Error:
        if cancel():raise InterruptedError('EPG_CANCELLED')
        return None
    finally:db.close()


def plans(portal):
    from epg_sources import configuration
    from guide_publish44 import source_id
    from epg_status import source_key
    from source_adapters import for_portal
    result=[]
    if portal.get('provider_epg_enabled',True):
        try:uri=portal.get('epg_url') or for_portal(portal).get_xmltv_epg_url() or ''
        except Exception:uri=''
        result.append(('provider','provider',dict(uri=uri,local=not uri.startswith(('http://','https://')),_plan_error54=not bool(uri)),0,'Anbieter-EPG'))
    from epg_report53 import label
    for rank,s in enumerate(configuration(portal['id'])['sources'],1):
        if s.get('enabled',True):result.append((source_id(s,rank),source_key(s),s,rank,label(s.get('name'))))
    return result


def run(portal,cancel=lambda:False,status=lambda *a:None):
    from portals import get_by_id
    if get_by_id(portal['id']) is None:raise ValueError('EPG_REQUIRES_PUBLISHED_PORTAL')
    from stream_epg import portal_lease44
    with portal_lease44(portal['id']) as held:
        if not held:raise OSError('EPG_IMPORT_BUSY')
        return _run(portal,cancel,status)


def _run(portal,cancel,status):
    from epg_gate46 import access
    from guide_store import path as guide_path
    from stream_epg import active_streams,import_source,publish_stages44,discard_stages44
    from epg_sources import configuration
    from epg_status import update
    from epg_report53 import observing,started,source_done
    state=prepare(portal);state.update(phase='RUNNING',updated=time.time());write(portal,state)
    try:configured=plans(portal)
    except Exception:
        state.update(phase='PARTIAL',code='SOURCE_UNAVAILABLE');write(portal,state);raise
    if not configured:
        state['phase']='NONE';write(portal,state);return state
    streams=list(active_streams(portal));mappings=configuration(portal['id'])['mappings']
    if not streams:
        state.update(phase='PARTIAL',code='WAIT_ACTIVE_CATALOG');write(portal,state);return state
    try:
        with observing(portal['id']) as report:
            authorized=None
            for number,(identity,key,source,rank,name) in enumerate(configured,1):
                if cancel():raise InterruptedError('EPG_CANCELLED')
                prefix='EPG-Quelle '+str(number)+' von '+str(len(configured))+' · '+name
                if source.get('_plan_error54'):
                    state['sources'][identity]=dict(code='SOURCE_UNAVAILABLE');write(portal,state)
                    started(portal['id'],key,identity,rank);source_done(portal['id'],identity,'SOURCE_UNAVAILABLE')
                    update(portal['id'],key,'SOURCE_UNAVAILABLE',running=False)
                    status(None,prefix+'\nQuelle derzeit nicht verfügbar; weitere Quellen werden unabhängig geprüft.')
                    continue
                fingerprint=signature(portal,source,rank);old=state['sources'].get(identity,{})
                if old.get('code')=='READY' and old.get('fingerprint')==fingerprint and 0<=time.time()-old.get('completed',0)<86400:
                    actual=stored(portal,identity,cancel,status)
                    if actual and actual==old.get('verified'):
                        status(None,prefix+'\nBereits vollständig geprüft · '+str(actual['rows'])+' Sendungen');continue
                if authorized is None:
                    authorized=access(guide_path())
                    if authorized not in ('READY','NOT_CREATED'):
                        state.update(phase='PARTIAL',code=authorized);write(portal,state)
                        update(portal['id'],'refresh',authorized,running=False)
                        return state
                previous_generation=old.get('generation','')
                if isinstance(previous_generation,str) and len(previous_generation)==32 and all(c in '0123456789abcdef' for c in previous_generation):
                    exists=False
                    if os.path.isfile(guide_path()):
                        db=sqlite3.connect('file:'+quote(guide_path(),safe='/')+'?mode=ro',uri=True,timeout=.1)
                        try:exists=bool(db.execute("SELECT 1 FROM sqlite_master WHERE name='xml_stage'").fetchone())
                        finally:db.close()
                    if exists:discard_stages44([dict(generation=previous_generation,meta_pid46=str(portal['id']))])
                generation=uuid.uuid4().hex
                state['sources'][identity]=dict(code='RUNNING',fingerprint=fingerprint,generation=generation);write(portal,state)
                started(portal['id'],key,identity,rank);stage=None
                def progress(value):
                    phase={'DOWNLOAD':'Download läuft','PARSE':'XMLTV-Datei wird verarbeitet und Sendern zugeordnet','SAVING':'EPG-Daten werden gespeichert'}.get(value['phase'],'Quelle wird geprüft')
                    status(None,prefix+'\n'+phase+'\n'+str(value.get('bytes',0))+' Bytes · '+str(value.get('programmes',0))+' Sendungen gelesen · '+str(value.get('stored',0))+' zugeordnet')
                status(None,prefix+'\nDownload läuft')
                try:
                    stage=import_source(portal['id'],source,rank,streams,mappings,cancel=cancel,stage_only=True,progress=progress,generation54=generation)
                    status(None,prefix+'\nEPG-Daten werden gespeichert')
                    outcome=publish_stages44(portal['id'],[stage],cancel=cancel)[0]
                    actual=stored(portal,identity,cancel,status)
                    if not actual or not actual['rows']:raise ValueError('EPG_PUBLICATION_UNVERIFIED')
                    state['sources'][identity]=dict(code='READY',fingerprint=fingerprint,completed=time.time(),verified=actual)
                    write(portal,state)
                    counts=stage['counts'];update(portal['id'],key,'READY',running=False,source_index=rank,channels=counts['channels'],programmes=counts['stored'],bytes=counts['bytes'])
                    source_done(portal['id'],identity,'READY',counts,outcome)
                    status(None,prefix+'\nQuelle erfolgreich abgeschlossen · '+str(actual['rows'])+' gespeicherte Sendungen')
                except InterruptedError:raise
                except Exception as exc:
                    from epg_errors import failure_details
                    code,fields=failure_details(exc,getattr(exc,'xcmate_stage','MERGE'))
                    state['sources'][identity]=dict(code=code,fingerprint=fingerprint);write(portal,state)
                    update(portal['id'],key,code,running=False,**fields);source_done(portal['id'],identity,code)
                    status(None,prefix+'\nQuelle nicht abgeschlossen. Portal und bisherige Daten bleiben erhalten.')
                finally:
                    if stage:discard_stages44([stage])
            state['phase']='READY' if all(state['sources'].get(p[0],{}).get('code')=='READY' for p in configured) else 'PARTIAL'
            state.update(updated=time.time(),code=state['phase']);write(portal,state)
            update(portal['id'],'refresh','READY' if state['phase']=='READY' else 'PARTIAL_SUCCESS',running=False,loaded=sum(state['sources'].get(p[0],{}).get('code')=='READY' for p in configured),failed=sum(state['sources'].get(p[0],{}).get('code')!='READY' for p in configured))
            report['result']=state['phase']=='READY'
            return state
    except BaseException:
        state.update(phase='PARTIAL',updated=time.time());write(portal,state)
        update(portal['id'],'refresh','CANCELLED',running=False)
        raise

