def build_url(base, **kwargs):
    import urllib.parse
    return base + '?' + urllib.parse.urlencode({k: v for k, v in kwargs.items() if v is not None})

def url_params(url):
    import urllib.parse
    qs = url.split('?', 1)[1] if '?' in url else ''
    return {k: v[0] for k, v in urllib.parse.parse_qs(qs).items()}


def safe_int(val, default: int = 0) -> int:
    if val is None:
        return default
    if isinstance(val, int):
        return val
    if isinstance(val, float):
        return int(val)
    s = str(val).strip()
    if not s or s.lower() in ('n/a', 'none', '-', '?', 'null'):
        return default
    import re
    m = re.match(r'^-?\d+', s)
    return int(m.group()) if m else default

def safe_float(val, default: float = 0.0) -> float:
    if val is None:
        return default
    if isinstance(val, (int, float)):
        return float(val)
    s = str(val).strip()
    if not s or s.lower() in ('n/a', 'none', '-', '?', 'null'):
        return default
    import re
    m = re.match(r'^-?\d+(\.\d+)?', s.replace(',', '.'))
    return float(m.group()) if m else default

def safe_year(val, default: int = 0) -> int:

    if val is None:
        return default
    if isinstance(val, int):
        return val if 1900 <= val <= 2100 else default
    s = str(val).strip()
    import re
    m = re.search(r'\b(19|20)\d{2}\b', s)
    return int(m.group()) if m else default


